import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.B9qR_F1m.js";const s="/bilder/zeichnungen.jpg",m=JSON.parse('{"title":"Zeichnungen","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/zeichnungen.md","filePath":"bereiche/zeichnungen.md"}'),a={name:"bereiche/zeichnungen.md"};function o(d,e,g,l,u,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="zeichnungen" tabindex="-1">Zeichnungen <a class="header-anchor" href="#zeichnungen" aria-label="Permalink to &quot;Zeichnungen&quot;">​</a></h1><p>Taktische Grafiken – CAP-Stationen, Frontlinien, Kill Boxes – zeichnest du hier auf die Karte. Shardwing schreibt sie als <strong>Zeichnungen in die .miz</strong>, sodass sie auf der F10-Karte in DCS erscheinen, und nutzt sie für Kneeboard-Karten und Geo Lines in der Cartridge.</p><p>Nur der Mission Designer sieht diesen Bereich.</p><p><img src="'+s+'" alt="Bereich Zeichnungen mit Werkzeugen, Ebenen und einem ausgewählten CAP" loading="lazy"></p><h2 id="werkzeuge" tabindex="-1">Werkzeuge <a class="header-anchor" href="#werkzeuge" aria-label="Permalink to &quot;Werkzeuge&quot;">​</a></h2><p>Links ein Werkzeug wählen und auf die Karte setzen:</p><table tabindex="0"><thead><tr><th>Gruppe</th><th>Grafiken</th></tr></thead><tbody><tr><td><strong>Orbits</strong></td><td><strong>CAP</strong> (Racetrack), <strong>AR</strong> (Tanker-Track), <strong>HOLD</strong></td></tr><tr><td><strong>Linien</strong></td><td><strong>FLOT</strong>, <strong>FLET</strong>, <strong>FEBA</strong>, <strong>FSCL</strong>, <strong>CFL</strong>, <strong>NFL</strong>, <strong>RFL</strong>, <strong>PL</strong> (Phase Line), <strong>LD</strong> (Line of Departure), <strong>BDY</strong> (Grenze)</td></tr><tr><td><strong>Gebiete</strong></td><td><strong>KB</strong> (Kill Box), <strong>ROZ</strong>, <strong>NFA</strong>, <strong>RFA</strong>, <strong>MRR</strong></td></tr><tr><td><strong>Punkte</strong></td><td><strong>IP</strong>, <strong>CP</strong></td></tr><tr><td><strong>Freie Formen</strong></td><td>Linie, Fläche, Kreis, Rechteck, Pfeil, Text</td></tr><tr><td><strong>Planungspunkte</strong> (Designer)</td><td><strong>RV</strong>, <strong>Marshal</strong>, <strong>Holding</strong>, <strong>CP</strong>, <strong>IP</strong>, <strong>Push</strong>, <strong>Fence</strong>, <strong>AR</strong></td></tr></tbody></table><p>Die Grafiken folgen den NATO-Darstellungen: FLOT und FLET mit Halbkreisen, FEBA mit Dreiecken, Kill Boxes mit Beschriftung.</p><h2 id="bearbeiten" tabindex="-1">Bearbeiten <a class="header-anchor" href="#bearbeiten" aria-label="Permalink to &quot;Bearbeiten&quot;">​</a></h2><ul><li><strong>Anklicken</strong> wählt eine Grafik oder eine bestehende Zeichnung aus der Mission.</li><li>Der <strong>weiße Griff</strong> verschiebt sie, die <strong>kleinen Punkte</strong> formen sie.</li><li>Beim <strong>CAP</strong> stellt der zweite Griff <strong>Kurs und Leglänge</strong> ein.</li><li>Linien und Flächen setzt du Punkt für Punkt; <kbd>Enter</kbd> schließt ab, <kbd>Esc</kbd> bricht ab.</li><li><kbd>Entf</kbd> oder <kbd>⌫</kbd> löscht die Auswahl.</li></ul><p>Im Panel darunter stellst du die gewählte Grafik genau ein: Name und Zusatz (Frequenz, DTG …), Position und Maße in NM, beim CAP Inbound-Kurs, Leglänge und Kurvendurchmesser, beim AR-Track Tanker, Frequenz und TACAN. Für Linien gibt es Muster (Linie, Strich-Punkt, Dreiecke, Kreuze, Drahtzaun …), dazu Farbe, Deckkraft, Füllung und Schriftgröße. <strong>Punkte umdrehen</strong> lässt Halbkreise und Dreiecke zur anderen Seite zeigen.</p><h2 id="planungspunkte" tabindex="-1">Planungspunkte <a class="header-anchor" href="#planungspunkte" aria-label="Permalink to &quot;Planungspunkte&quot;">​</a></h2><p>Planungspunkte sind deine Treffpunkte für das Timing: ein Rendezvous, ein Marshal, ein Holding, CP oder IP. Du setzt sie wie eine Grafik. Auf der Karte sitzt eine gelbe Raute genau auf der Koordinate, der Name steht daneben (<em>RV ALPHA</em>, <em>MARSHAL ALPHA</em> …); beim Holding ist es ein Punkt.</p><ul><li><strong>Wer ihn sieht.</strong> Ein Flight sieht einen Punkt in Shardwing erst, wenn er dort eingetragen ist – beschriftet mit seiner eigenen Zeit und seinem Band, z. B. <em>MARSHAL ALPHA · H−10 · FL180–190</em>. Punkte, an denen er nicht eingetragen ist, und die Zeiten der anderen sieht er nicht. Ins F10 kommen die Punkte nicht (außer dem Holding-Muster). Dazu bekommt der Flight eine <strong>Sollzeit</strong> mit Name, Zeit, Höhenband und Koordinate und setzt im <a href="./dtc#tos-rechner">TOS-Rechner</a> einen Steerpoint dorthin.</li><li><strong>Flights an diesem Punkt:</strong> Jeder Flight bekommt seine eigene Zeit, ein Fenster und ein <strong>Höhenband</strong>. So sammeln sich mehrere Flights am selben Marshal, ohne dass du den Punkt mehrfach anlegst. <ul><li><strong>Zeiten staffeln</strong> – ab der ersten Zeit alle <em>N</em> Minuten (0 = alle gleich).</li><li><strong>Bänder stapeln</strong> – ab FL <em>x</em>, je Band <em>y</em> ft dick, mit <em>z</em> ft Abstand.</li><li>Überlappen zwei Bänder bei etwa gleicher Zeit (bis 10 Minuten auseinander), steht eine Warnung darunter und unter <em>Prüfungen</em>.</li></ul></li><li><strong>Verschieben oder umbenennen</strong> ändert die Sollzeit bei allen Flights dort.</li><li><strong>Holding:</strong> Ein Holding-Punkt zeichnet zusätzlich ein <strong>HOLD-Muster</strong>, das alle Flights auf der Karte und im F10 sehen – mit Inbound-Kurs, Leg, Breite und Kurvenrichtung (Standard rechts) und beschriftet mit allen Bändern dort, z. B. <em>FL180–FL230</em>.</li><li><strong>AR am Tanker:</strong> Ein AR-Punkt lässt sich unter <em>Am Track von</em> mit einem Tanker verbinden. Er sitzt dann auf dem Beginn des Tracks (P1) und wandert mit, wenn du den Track verschiebst, drehst oder die Seite tauschst. Die Flights dort bekommen diese Koordinate für ihre DTC.</li><li><strong>Ohne Zeit:</strong> Ein Haken bei <em>ohne Zeit</em> macht aus der Sollzeit eines Flights einen reinen Ort. Er erscheint nur in seiner DTC (TOS-Rechner), nicht im Timing, nicht auf der Lineup Card und wird nicht geprüft.</li><li><strong>Punkt löschen</strong> lässt die Zeiten der Flights als normale Sollzeiten mit Koordinate stehen.</li></ul><p>Eine Sollzeit mit Ort, die du im <a href="./timing#ein-flight-im-detail">Timing</a> angelegt hast, machst du dort mit <strong>◆ Als Planungspunkt</strong> zu einem Punkt. Die Liste aller Punkte steht links unter <em>Planungspunkte</em> und im Timing unter <em>Treffpunkte</em>.</p><h2 id="ebenen" tabindex="-1">Ebenen <a class="header-anchor" href="#ebenen" aria-label="Permalink to &quot;Ebenen&quot;">​</a></h2><p>DCS kennt fünf Zeichenebenen. Oben links wählst du, auf welche neue Objekte kommen:</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Wer sieht sie auf F10</th></tr></thead><tbody><tr><td><strong>Blue</strong></td><td>nur Blau</td></tr><tr><td><strong>Red</strong></td><td>nur Rot</td></tr><tr><td><strong>Neutral</strong></td><td>nur Neutrale</td></tr><tr><td><strong>Common</strong></td><td>alle</td></tr><tr><td><strong>Author</strong></td><td>nur im Mission Editor</td></tr></tbody></table><p>Die Liste <strong>Ebenen</strong> unten zeigt, wie viele Objekte jede Ebene hat; aufgeklappt siehst du sie einzeln.</p><p><strong>Alle Einheiten zeigen</strong> blendet alle Boden-, See- und Static-Gruppen der Mission ein – praktisch, um eine FLOT an echten Stellungen entlang zu ziehen.</p><h2 id="wo-zeichnungen-auftauchen" tabindex="-1">Wo Zeichnungen auftauchen <a class="header-anchor" href="#wo-zeichnungen-auftauchen" aria-label="Permalink to &quot;Wo Zeichnungen auftauchen&quot;">​</a></h2><ul><li><strong>F10-Karte</strong> in DCS, je nach Ebene</li><li><strong>Kneeboard-Karten</strong>: Lineup Card, Lagekarte, Ausschnitte – jeweils die Ebene der Koalition und Common, so wie der Flight sie auf F10 sähe</li><li><strong>Cartridge</strong>: F-16 als Geo Lines, F/A-18 als FLOT/FAOR/CAP-Punkte – über <strong>Aus Grafik übernehmen</strong> im <a href="./dtc">DTC</a></li></ul>',22)])])}const b=n(a,[["render",o]]);export{m as __pageData,b as default};
